current.custom_css:
.sf__btn.sf__btn-link:after, .sf__btn.sf__btn-link:before, 
a.sf__btn.sf__btn-link:after, a.sf__btn.sf__btn-link:before, 
button.sf__btn.sf__btn-link:after, button.sf__btn.sf__btn-link:before {
  height: 1px;
}

.section__subheading, 
.sf__index-image-card .image__card-subheading {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 10px;
}

.section__subheading {
  color: #999;
}

.sf-header .sf-menu-item a.sf__parent-item {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-size: 14px;
  margin-left: 1rem;
  margin-right: 1rem;
}

.sf__index-hero .sf-hero__content .sf-hero__text {
  color: #000;
  line-height: 1.5;
}

.sf__index-hero .sf-hero__content .sf-hero__title {
  line-height: 1.275;
  margin-bottom: 10px;
}

.sf__index-icon-box .sf-icon-box__text h3 {
  font-family: 'SF-Body-font';
  font-size: 20px;
  line-height: 1.35;
  margin-bottom: 10px;
  font-weight: 700;
}

.sf__index-image-card .image__card-subheading {
  color: #000;
}

.sf__index-image-card .image__card-heading {
  line-height: 1.3;
  margin-bottom: 10px;
}

.sf__blog-card .sf__blog-cardContent .sf__blog-cardDate, 
.sf__blog-card .sf__blog-cardContent .sf__blog-cardTags {
  font-size: 12px;
  color: #999;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: 1px;
  line-height: 1.33;
}

.sf__blog-card .sf__blog-cardContent .sf__blog-cardTitle a {
  font-size: 20px;
  font-family: 'SF-Body-font';
  font-weight: 700;
  line-height: 1.35;
}

.sf-footer .sf-footer__block ul li a,
.sf__footer-block-our_store .sf__accordion-content {
  font-size: 14px;
  text-transform: uppercase;
}

.sf__footer-block-our_store .sf__accordion-content .block-text p:first-child {
  margin-bottom: 16px;
}

.sf__footer-block-our_store .social-media-links {
  margin-left: -6px;
  margin-right: -6px;
}

.sf__footer-block-our_store .social-media-links a {
  width: 40px;
  height: 40px;
  border: 1px solid rgba(0,0,0, .1);
  border-radius: 50%;
  margin: 0 6px;
  display: flex;
  justify-content: center;
  align-items: center;
} 

.sf__footer-block-our_store .social-media-links a svg { 
  width: 16px;
  height: 16px;
}

.sf-footer form.sf__footer-form-newsletter.form__style-minimal .sf__newletter__form-input {
  border-color: rgba(0,0,0, .3);
}

.sf-footer form.sf__footer-form-newsletter.form__style-minimal .sf__form-submit {
  color: #000;
}

.sf__index-instagram .section-py {
  padding-bottom: 0;
}

.sf__pcard-name {
  font-family: 'SF-Body-font';
  font-weight: 700;
}

@media screen and (min-width: 1280px) {
  .sf__index-hero .sf-hero__content .sf-hero__title {
  	font-size: 100px;
  }

  .sf__index-hero .sf-hero__content .sf-hero__text {
    font-size: 24px;
    margin-bottom: 40px;
  }

  .sf__index-image-card .image__card-heading { 
    font-size: 54px;
  }

  .sf__index-image-card .image-card__content {
    padding-top: 60px;
  }

  .sf__index-product-card .sf__pcard {
    max-width: 60%;
    margin: 0 auto;
  }

  .sf-footer .sf__footer-middle .sf-footer__block {
    text-align: center;
  }

  .sf-footer .sf__footer-block-title {
    font-size: 32px;
  }

  .sf__footer-block-our_store .social-media-links {
    justify-content: center;
  }
}

@media screen and (min-width: 1536px) {
  .sf__index-hero .sf-hero__content .sf-hero__title {
  	font-size: 120px;
  }
}

@media screen and (max-width: 767px) {
  .sf__index-hero .sf-hero__content .sf-hero__title {
    font-size: 42px;
  }

  .sf__footer-bottom-inner .sf-footer__left {
    text-align: left;
  }

  .sf__footer-bottom-inner .sf-footer__right {
    justify-content: flex-start;
  }
}
